using System;
using UnityEngine;

namespace MagicMotion.Core
{
    public static class RuntimeMaterialFactory
    {
        private const string LitShaderName = "Universal Render Pipeline/Lit";
        private const string TrailShaderName = "Universal Render Pipeline/Particles/Unlit";

        // Generated by ProjectBootstrap and kept under Resources so it is always
        // shipped. It carries the only asset references to the URP shaders that
        // the runtime otherwise resolves by name through Shader.Find.
        private const string LitMaterialResource = "Materials/StrippingAnchorLit";
        private const string TrailMaterialResource = "Materials/StrippingAnchorTrail";

        public static Material CreateLit(Color color, Color emission)
        {
            var material = CreateFromResourceOrShader(LitMaterialResource, LitShaderName);
            ApplyColor(material, color);
            ApplyEmission(material, emission);
            return material;
        }

        public static Material CreateTrail(Color color)
        {
            var material = CreateFromResourceOrShader(TrailMaterialResource, TrailShaderName);
            ApplyColor(material, color);
            ApplyTrailSettings(material);
            return material;
        }

        // The trail is a TrailRenderer: it only fades out if the material actually blends.
        // A freshly created URP particle material defaults to opaque, so force transparent
        // alpha blending here instead of relying on the imported anchor's saved state.
        private static void ApplyTrailSettings(Material material)
        {
            if (!material.HasProperty("_Surface"))
            {
                return;
            }

            material.SetFloat("_Surface", 1f);
            material.SetFloat("_Blend", 0f);
            material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");

            if (material.HasProperty("_SrcBlend"))
            {
                material.SetInt("_SrcBlend", (int)UnityEngine.Rendering.BlendMode.SrcAlpha);
                material.SetInt("_DstBlend", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetInt("_SrcBlendAlpha", (int)UnityEngine.Rendering.BlendMode.One);
                material.SetInt("_DstBlendAlpha", (int)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
                material.SetInt("_ZWrite", 0);
            }

            if (material.HasProperty("_ColorMode"))
            {
                // Multiply keeps the TrailRenderer start/end color gradient.
                material.SetFloat("_ColorMode", 0f);
            }

            material.SetOverrideTag("RenderType", "Transparent");
            material.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent;
        }

        private static Material CreateFromResourceOrShader(string resource, string shaderName)
        {
            if (!string.IsNullOrEmpty(resource))
            {
                var template = Resources.Load<Material>(resource);
                if (template != null)
                {
                    return new Material(template);
                }
            }

            var shader = Shader.Find(shaderName);
            if (shader != null)
            {
                return new Material(shader);
            }

            var fallback = Shader.Find("Sprites/Default");
            if (fallback == null)
            {
                throw new InvalidOperationException(
                    $"Neither '{shaderName}' nor 'Sprites/Default' is available at runtime. " +
                    "Run Magic Motion > Initialize Project so the stripping anchor is created.");
            }

            Debug.LogWarning(
                $"[MagicMotion.Core] '{shaderName}' is unavailable, falling back to Sprites/Default.");
            return new Material(fallback);
        }

        private static void ApplyColor(Material material, Color color)
        {
            material.color = color;
            if (material.HasProperty("_BaseColor"))
            {
                material.SetColor("_BaseColor", color);
            }
        }

        private static void ApplyEmission(Material material, Color emission)
        {
            if (!material.HasProperty("_EmissionColor"))
            {
                return;
            }

            material.EnableKeyword("_EMISSION");
            material.SetColor("_EmissionColor", emission);
        }
    }
}
